public:
    vector<int> productExceptSelf(vector<int>& nums) {
        // 先从左到右累乘前缀积，再从右到左累乘后缀积
        int n = (int)nums.size();
        vector<int> res(n, 1);
        int prefix = 1;
        for (int i = 0; i < n; i++) { res[i] = prefix; prefix *= nums[i]; }
        int suffix = 1;
        for (int i = n - 1; i >= 0; i--) { res[i] *= suffix; suffix *= nums[i]; }
        return res;
    }
};

